const nextBillingChargeEnd = `-- name: NextBillingChargeEnd :one
SELECT ends_at FROM billing_charges
WHERE account_id = $1 AND plan = $2
  AND ends_at > $3::timestamptz AND qty > canceled_qty
ORDER BY ends_at
LIMIT 1
`

type NextBillingChargeEndParams struct {
	AccountID uuid.UUID
	Plan      string
	After     time.Time
}

// The next renewal boundary: the earliest end after `after` of a lot of `plan` with seats left.
func (q *Queries) NextBillingChargeEnd(ctx context.Context, arg NextBillingChargeEndParams) (time.Time, error) {
	row := q.db.QueryRow(ctx, nextBillingChargeEnd, arg.AccountID, arg.Plan, arg.After)
	var ends_at time.Time
	err := row.Scan(&ends_at)
	return ends_at, err
}

